if (!window.storage) {
  window.storage = {
    get: async (key) => {
      const val = localStorage.getItem(key);
      return val ? { value: val } : null;
    },
    set: async (key, value) => {
      localStorage.setItem(key, value);
      return true;
    },
    delete: async (key) => {
      localStorage.removeItem(key);
      return true;
    }
  };
}

