                  border: uiDensity === d.id ? "2px solid #6366f1" : "1px solid rgba(139, 126, 116, 0.2)",
                  background: uiDensity === d.id ? "rgba(99, 102, 241, 0.15)" : "rgba(255, 255, 255, 0.6)",
                  color: "#5a4a42",
